ENGINES = {e["name"]: e for e in CAPABILITIES["engines"]}

def expected_registry(settings):
    macros = set(re.findall(r"-D(\w+)", settings.get("CCFLAG", "")))
    return {e["name"]: e["id"] for e in ENGINES.values() if enabled(e["cpp"], macros)}

def gate_plan(registry):
    rows = []
    for name, identifier in registry.items():
        e = ENGINES[name]
        if identifier != e["id"] or not e["gate"].get("oracle"):
            raise ValueError(name+": no matching retained public-gate oracle declaration")
        rows.append(dict(engine=name, id=identifier, **e["gate"]))
    return rows
